CREATE OR REPLACE FUNCTION public.assassin_abandon_contract(_character_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.owns_character(_character_id) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  PERFORM set_config('app.trusted_rpc', 'true', true);
  UPDATE public.characters
     SET active_contract = NULL
   WHERE id = _character_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.assassin_take_contract(_character_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _c RECORD;
  _hall_region uuid;
  _pick RECORD;
  _contract jsonb;
BEGIN
  IF NOT public.owns_character(_character_id) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT * INTO _c FROM public.characters WHERE id = _character_id FOR UPDATE;
  IF _c IS NULL THEN RAISE EXCEPTION 'Character not found'; END IF;
  IF _c.class::text <> 'assassin' THEN
    RAISE EXCEPTION 'Only assassins can take contracts';
  END IF;
  IF _c.active_contract IS NOT NULL THEN
    RAISE EXCEPTION 'You already have an active contract';
  END IF;

  -- Region of the assassin hall (for tie-break preference).
  SELECT region_id INTO _hall_region
    FROM public.nodes WHERE class_hall = 'assassin' LIMIT 1;

  -- Eligible creatures: not boss, within level window, exist on a node with area.
  WITH eligible AS (
    SELECT DISTINCT ON (cr.id)
      cr.id, cr.name, cr.level, cr.rarity,
      n.area_id, a.name AS area_name, n.region_id
    FROM public.creatures cr
    JOIN public.nodes n ON n.id = cr.node_id
    JOIN public.areas a ON a.id = n.area_id
    WHERE cr.rarity <> 'boss'
      AND cr.level BETWEEN GREATEST(1, _c.level - 2) AND (_c.level + 1)
      AND n.area_id IS NOT NULL
  )
  SELECT * INTO _pick FROM eligible
  ORDER BY
    (region_id = _hall_region) DESC,
    abs(level - _c.level),
    random()
  LIMIT 1;

  IF _pick IS NULL THEN
    RAISE EXCEPTION 'No suitable targets found for your level right now';
  END IF;

  _contract := jsonb_build_object(
    'creature_id', _pick.id,
    'creature_name', _pick.name,
    'area_id', _pick.area_id,
    'area_name', _pick.area_name,
    'target_level', _pick.level,
    'rarity', _pick.rarity,
    'issued_at', extract(epoch from now())::bigint
  );

  PERFORM set_config('app.trusted_rpc', 'true', true);
  UPDATE public.characters
     SET active_contract = _contract
   WHERE id = _character_id;

  RETURN _contract;
END;
$function$

CREATE OR REPLACE FUNCTION public.node_tick_commit(_encounter_id uuid, _claim_token uuid, _candidate_tick integer, _expected_last_tick integer, _expected_state_version bigint, _intent_ids uuid[], _proposed jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE row jsonb; result jsonb; current_version bigint; stance_target uuid; locked_node uuid; encounter_node uuid;
BEGIN
 -- Match the direct predecessor: ordered origin/moved-destination node locks
 -- must precede encounter, fighter and stance row locks. Reacquisition by the
 -- predecessor is transaction-reentrant; it cannot add a new node after this.
 SELECT node_id INTO encounter_node FROM public.node_encounter WHERE id=_encounter_id;
 FOR locked_node IN
   SELECT node_id FROM (
     SELECT encounter_node AS node_id
     UNION
     SELECT (departure->>'destination_node_id')::uuid
     FROM jsonb_array_elements(coalesce(_proposed->'departures','[]'::jsonb)) departure
     WHERE departure->>'outcome'='moved'
   ) nodes WHERE node_id IS NOT NULL ORDER BY node_id
 LOOP
   PERFORM pg_advisory_xact_lock(hashtextextended('combat_enter_node:'||locked_node::text,0));
 END LOOP;
 PERFORM 1 FROM public.node_encounter WHERE id=_encounter_id FOR UPDATE;
 IF EXISTS (SELECT 1 FROM public.node_encounter WHERE id=_encounter_id
   AND node_id IS DISTINCT FROM encounter_node)
 THEN RAISE EXCEPTION 'stance_encounter_node_changed'; END IF;
 -- Membership is historical within this encounter, not post-resolution presence.
 -- UNION also avoids repeated locks for targets present in several stance arrays.
 FOR stance_target IN
   SELECT (value->>'character_id')::uuid FROM jsonb_array_elements(coalesce(_proposed->'stance_fence','[]'::jsonb))
   UNION SELECT (value->>'character_id')::uuid FROM jsonb_array_elements(coalesce(_proposed->'stance_updates','[]'::jsonb))
   UNION SELECT value::uuid FROM jsonb_array_elements_text(coalesce(_proposed->'stance_clear_character_ids','[]'::jsonb))
   ORDER BY 1
 LOOP
   IF stance_target IS NULL THEN RAISE EXCEPTION 'stance_target_invalid'; END IF;
   PERFORM 1 FROM public.node_fighter
     WHERE encounter_id=_encounter_id AND character_id=stance_target
     ORDER BY id FOR SHARE;
   IF NOT FOUND THEN RAISE EXCEPTION 'stance_target_outside_encounter'; END IF;
 END LOOP;
 FOR row IN SELECT value FROM jsonb_array_elements(coalesce(_proposed->'stance_fence','[]'::jsonb)) LOOP
   SELECT version INTO current_version FROM public.character_stance
    WHERE character_id=(row->>'character_id')::uuid AND ability_key=row->>'ability_key' FOR UPDATE;
   IF current_version IS DISTINCT FROM (row->>'version')::bigint THEN RETURN jsonb_build_object('ok',false,'kind','stale_stance'); END IF;
 END LOOP;
 result:=public.node_tick_commit_without_character_stances(_encounter_id,_claim_token,_candidate_tick,_expected_last_tick,
   _expected_state_version,_intent_ids,_proposed);
 IF result->>'ok'='true' AND result->>'kind'='committed' THEN
   FOR row IN SELECT value FROM jsonb_array_elements(coalesce(_proposed->'stance_updates','[]'::jsonb)) LOOP
     UPDATE public.character_stance SET state=row->'state',version=version+1,updated_at=clock_timestamp()
      WHERE character_id=(row->>'character_id')::uuid AND ability_key=row->>'ability_key' AND version=(row->>'version')::bigint;
     IF NOT FOUND THEN RAISE EXCEPTION 'stale stance update'; END IF;
   END LOOP;
   DELETE FROM public.character_stance WHERE character_id IN
    (SELECT value::text::uuid FROM jsonb_array_elements_text(coalesce(_proposed->'stance_clear_character_ids','[]'::jsonb)));
   UPDATE public.character_stance_request SET committed_at=clock_timestamp()
    WHERE encounter_id=_encounter_id AND intent_id=ANY(_intent_ids) AND committed_at IS NULL;
 END IF;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.restrict_party_leader_updates()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _stat_delta integer;
  _points_delta integer;
  _respec_delta integer;
  _trusted boolean;
BEGIN
  _trusted := coalesce(current_setting('app.trusted_rpc', true), '') = 'true';

  IF auth.uid() = NEW.user_id THEN
    NEW.level := OLD.level;
    NEW.xp := OLD.xp;
    NEW.user_id := OLD.user_id;

    IF NOT _trusted THEN
      NEW.race := OLD.race;
      NEW.class := OLD.class;
      NEW.is_classless := OLD.is_classless;
    END IF;

    IF OLD.soulforged_item_created = true THEN
      NEW.soulforged_item_created := true;
    END IF;

    IF NOT _trusted THEN
      NEW.soulring_tier := OLD.soulring_tier;
      NEW.soulring_inventory_id := OLD.soulring_inventory_id;
      NEW.king_slayer_at := OLD.king_slayer_at;
    END IF;

    IF NEW.gold > OLD.gold AND NOT _trusted THEN
      NEW.gold := OLD.gold;
    END IF;

    IF NOT _trusted THEN
      NEW.max_hp := OLD.max_hp;
      NEW.max_cp := OLD.max_cp;
      NEW.max_mp := OLD.max_mp;
      NEW.ac := OLD.ac;

      NEW.hp := LEAST(GREATEST(COALESCE(NEW.hp, 0), 0), OLD.max_hp);
      NEW.mp := LEAST(GREATEST(COALESCE(NEW.mp, 0), 0), OLD.max_mp);
      NEW.cp := LEAST(GREATEST(COALESCE(NEW.cp, 0), 0), OLD.max_cp);

      NEW.reserved_buffs := OLD.reserved_buffs;
      NEW.stance_state := OLD.stance_state;

      NEW.bhp_trained := OLD.bhp_trained;

      NEW.family_id := OLD.family_id;
      NEW.family_name := OLD.family_name;
      NEW.family_changed_after_creation := OLD.family_changed_after_creation;

      -- Contract state: server RPCs only.
      NEW.active_contract := OLD.active_contract;
      NEW.contracts_completed := OLD.contracts_completed;
    END IF;

    IF NEW.bhp > OLD.bhp THEN
      NEW.bhp := OLD.bhp;
    END IF;

    IF NEW.rp_total_earned > OLD.rp_total_earned THEN
      NEW.rp_total_earned := OLD.rp_total_earned;
    END IF;

    IF NEW.respec_points > OLD.respec_points THEN
      NEW.respec_points := OLD.respec_points;
    END IF;

    _stat_delta := (NEW.str - OLD.str) + (NEW.dex - OLD.dex) + (NEW.con - OLD.con)
                 + (NEW.int - OLD.int) + (NEW.wis - OLD.wis) + (NEW.cha - OLD.cha);
    _points_delta := OLD.unspent_stat_points - NEW.unspent_stat_points;
    _respec_delta := OLD.respec_points - NEW.respec_points;

    IF _respec_delta <= 0 THEN
      IF _stat_delta > 0 AND _stat_delta != _points_delta THEN
        NEW.str := OLD.str;
        NEW.dex := OLD.dex;
        NEW.con := OLD.con;
        NEW.int := OLD.int;
        NEW.wis := OLD.wis;
        NEW.cha := OLD.cha;
        NEW.unspent_stat_points := OLD.unspent_stat_points;
      END IF;
      IF NEW.unspent_stat_points > OLD.unspent_stat_points THEN
        NEW.unspent_stat_points := OLD.unspent_stat_points;
      END IF;
    END IF;

    NEW.gold := GREATEST(NEW.gold, 0);
    NEW.ac := LEAST(GREATEST(NEW.ac, 1), 100);
    NEW.max_hp := LEAST(GREATEST(NEW.max_hp, 1), 10000);
    NEW.max_cp := LEAST(GREATEST(NEW.max_cp, 0), 5000);
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$
